import{_ as a,c as i,a as n,o as d}from"./app-Cz6XCkF7.js";const r={};function c(s,e){return d(),i("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-10-12-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-10-12-资讯日报"><span>2026-10-12 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="liam-fedus-ai该进实体实验室了" tabindex="-1"><a class="header-anchor" href="#liam-fedus-ai该进实体实验室了"><span>Liam Fedus：AI该进实体实验室了</span></a></h3><p>Liam Fedus：当前AI在聊天、编程、数学领域的突破，依赖可验证数据或自然交互产品形态；互联网语料已接近枯竭，AI攻克物理世界难题必须搭建实体实验室。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=8542d73d8eb0290d9649d330f00b380b0345a296ef06c27094c345b3d5b732e2e90f0f37fcf6&amp;idx=1&amp;mid=2651062101&amp;sn=4fa34c4604540b68c52a577eec0cead7#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="微软推出快速决策模型microsoft-decision-1" tabindex="-1"><a class="header-anchor" href="#微软推出快速决策模型microsoft-decision-1"><span>微软推出快速决策模型Microsoft-Decision-1</span></a></h3><p>微软推出Microsoft-Decision-1专门处理AI工作流中固定选项判断，拆分高频决策任务，速度比通用大模型快上百倍、成本低200倍，需搭配通用大模型或人工复核。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3Mzg5MjY3Nw==&amp;chksm=cf247bf0568a3d9d140787d1d4ca08bb2c5fd38db35b91a2b9ed5b87b83e29f0d04c8b837187&amp;idx=1&amp;mid=2247527074&amp;sn=4de65c7b8eb0d4082ef4b76a71c54e16#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai攻克千禧难题-人类看不懂" tabindex="-1"><a class="header-anchor" href="#openai攻克千禧难题-人类看不懂"><span>OpenAI攻克千禧难题 人类看不懂</span></a></h3><p>MIT教授Justin Solomon称，OpenAI已攻克千禧年难题纳维-斯托克斯方程，证明正确但顶尖学者都读不懂；陶哲轩直指AI可解释性困境，传统科研范式正遭遇颠覆<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0f161a5ae3d79bfb2f6d0c296b1c66aa7663e2560867dd94189ab90648586fa651bb8c505d2&amp;idx=2&amp;mid=2652733527&amp;sn=e6420d20408ef4e2c8055a2ea3d15a4d#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai悄悄上架生命科学新模型" tabindex="-1"><a class="header-anchor" href="#openai悄悄上架生命科学新模型"><span>OpenAI悄悄上架生命科学新模型</span></a></h3><p>OpenAI首推独立品牌生命科学大模型产品线，新增药物发现方向新模型，定位药企工具供应商不碰研发管线。AI+药物发现付费能力强，但验证周期长，商业化仍待验证。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=86ccb01960b2ab7b88d1c0735577c0246e4279496cdead53d81b0cbda73767f74f4f1e0c4f08&amp;idx=1&amp;mid=2649806899&amp;sn=97eaee71f6d9d06a8c2eff13bedb8277#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="英飞凌icic-2026-ai走进物理世界" tabindex="-1"><a class="header-anchor" href="#英飞凌icic-2026-ai走进物理世界"><span>英飞凌ICIC 2026：AI走进物理世界</span></a></h3><p>英飞凌判断AI正从云端走向物理世界，半导体竞争已从单器件比拼转向全链路系统方案能力竞争，本土芯片厂商需补齐系统协同能力<a href="https://mp.weixin.qq.com/s?__biz=MzIwMzgzNTQ1Nw==&amp;chksm=975187e9941fb0c84dcbb0ed029ebd9fb975889988510fdf88c7b781b53820ebe1a9dec204e0&amp;idx=1&amp;mid=2247661947&amp;sn=3fc68c88c7602db8a58b6ef3ffd692bf#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="中科大团队造溯因世界模型获千万融资" tabindex="-1"><a class="header-anchor" href="#中科大团队造溯因世界模型获千万融资"><span>中科大团队造溯因世界模型获千万融资</span></a></h3><p>白泽通境推出带溯因能力的世界模型AWM，数据效率比现有方案高7倍，通过自研推理引擎可压缩部署到机器人端侧，已完成三个工业场景验证，成立三月获数千万融资。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85fc04f5ae273decb8503d8968c1c60701ad01a2f04c77a67ba19bda59c41e8007213bd2d6d7&amp;idx=3&amp;mid=2651062101&amp;sn=450dc47681e0de359cd4675203b3e3ee#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="从sigmoid到swiglu-读懂激活函数" tabindex="-1"><a class="header-anchor" href="#从sigmoid到swiglu-读懂激活函数"><span>从Sigmoid到SwiGLU 读懂激活函数</span></a></h3><p>ShuYini：梳理激活函数从饱和型Sigmoid/Tanh、硬门控ReLU，到平滑软门控GELU/SiLU，再到门控SwiGLU的演进，讲清各激活的优缺点与适用场景<a href="https://mp.weixin.qq.com/s?__biz=MzUzOTgwNDMzOQ==&amp;chksm=fbc6e820e81a32836049d4a06a32bbde3d418841d7fce17d92494bd613d5777a4aeb345cb82d&amp;idx=1&amp;mid=2247505380&amp;sn=01a2ebef510447e14a937766f65444b8#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="agent时代前端-三大ui协议协同模式" tabindex="-1"><a class="header-anchor" href="#agent时代前端-三大ui协议协同模式"><span>Agent时代前端：三大UI协议协同模式</span></a></h3><p>作者称，Agent时代自然语言适合传递任务，但表单、卡片等传统UI仍有不可替代的交互优势；三个标准可按需组合，不必一次性引入全部协议。<a href="https://mp.weixin.qq.com/s?__biz=Mzk1NzQ1ODk5NQ==&amp;chksm=c2fe60ba2b7e546c30e619e88686b2dd66433d1c61bff2ed7743257c3ad864c1d1208df71b53&amp;idx=1&amp;mid=2247526710&amp;sn=f179859f8016903003ad2444585f571a#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="人生周报v094-ai与人生感悟" tabindex="-1"><a class="header-anchor" href="#人生周报v094-ai与人生感悟"><span>人生周报v094：AI与人生感悟</span></a></h3><p>李继刚：AI复杂系统是演化出来的，非抄规划可得。Agent补短板落地会增加复杂度，模型进步会重归简单。重读《集装箱改变世界》，启发思考AI为何未显现在GDP中。<a href="https://mp.weixin.qq.com/s?__biz=MzkxMzc1NzM1Mw==&amp;chksm=c0c4a3de65c8f42a566ed6ba196be95ee56d60cc00bd342ceb602eb797562acfaa52eb658c55&amp;idx=1&amp;mid=2247485351&amp;sn=dea07a6b88910d6a493dfd312004d3d5#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="ai逆向一切-软件都将被迫开源" tabindex="-1"><a class="header-anchor" href="#ai逆向一切-软件都将被迫开源"><span>AI逆向一切，软件都将被迫开源</span></a></h3><p>开发者Brandon Thomas用Claude逆向重写Adobe全家桶开源，AI大幅压低逆向工程成本，所有本地软件将事实开源，原有软件商业模式被颠覆，注意力才是AI时代新护城河。<a href="https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA==&amp;chksm=f16caa0139bdaa996543533888a58a0472ecce941bb276ef8662856c5639bfc73bbbc4c6a9bb&amp;idx=1&amp;mid=2647686995&amp;sn=cc40a3488a2ea7652d2ab589056f40b4#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="全球首个机器人原生3d世界模型unitas" tabindex="-1"><a class="header-anchor" href="#全球首个机器人原生3d世界模型unitas"><span>全球首个机器人原生3D世界模型UNITAS</span></a></h3><p>跨维智能推出全球首个机器人任务原生3D世界模型UNITAS，将观察、动作、环境变化统一到三维空间，仅1.7B参数就超越多个大参数模型，横扫多项评测，真实机器人任务平均成功率达85%。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=856f3568cd3e1045da7dedfa2475ce43fd642f2b237b4fa324438034c47821b53ef279ba2158&amp;idx=1&amp;mid=2651062231&amp;sn=8ad6ead246eea7caacf03d1ab45e9d0e#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="清华开源veriloop-e2-推进黑洞信息悖论研究" tabindex="-1"><a class="header-anchor" href="#清华开源veriloop-e2-推进黑洞信息悖论研究"><span>清华开源VeriLoop E2 推进黑洞信息悖论研究</span></a></h3><p>清华团队提出，当前大模型自我裁决结果不可靠，需拆分探索权与提交权，模型生成候选，仅外部验证通过的结果可保留；该机制将黑洞信息悖论推进至定量完备性模量，项目已开源。<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9cd8591c0ddee1cb85cc6bd8e6f13748715a83c596fd43f2d38e5b01ab05cd62e40b85f3b8f&amp;idx=3&amp;mid=2247932309&amp;sn=43903282d14f5e89059beb4b21d11ced#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="清华团队样本分布训练刷新生成sota" tabindex="-1"><a class="header-anchor" href="#清华团队样本分布训练刷新生成sota"><span>清华团队样本分布训练刷新生成SOTA</span></a></h3><p>清华联合多校团队提出样本分布训练新方法，MGFlow拿下一步生图SOTA，性能超越同规模基线；Elastic Forcing仅用8张H200完成14B流式视频模型后训练，效果超越现有工业模型。<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85ccfe56683e0f1c8ef441e25105758ea159cee7f17048d6c64669417c88725bb32690aca7b8&amp;idx=2&amp;mid=2651062123&amp;sn=b21145b2907980bdd47215ed5e3491a7#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',34)]))}const p=a(r,[["render",c]]),l=JSON.parse('{"path":"/posts/2026-10-12.html","title":"AI日报：Liam Fedus：AI该进实体实验室了; 微软推出快速决策模型Microsoft-Decision-1; OpenAI攻克千禧难题 人类看不懂","lang":"zh-CN","frontmatter":{"date":"2026-10-12T00:00:00.000Z","title":"AI日报：Liam Fedus：AI该进实体实验室了; 微软推出快速决策模型Microsoft-Decision-1; OpenAI攻克千禧难题 人类看不懂"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"Liam Fedus：AI该进实体实验室了","slug":"liam-fedus-ai该进实体实验室了","link":"#liam-fedus-ai该进实体实验室了","children":[]},{"level":3,"title":"微软推出快速决策模型Microsoft-Decision-1","slug":"微软推出快速决策模型microsoft-decision-1","link":"#微软推出快速决策模型microsoft-decision-1","children":[]},{"level":3,"title":"OpenAI攻克千禧难题 人类看不懂","slug":"openai攻克千禧难题-人类看不懂","link":"#openai攻克千禧难题-人类看不懂","children":[]},{"level":3,"title":"OpenAI悄悄上架生命科学新模型","slug":"openai悄悄上架生命科学新模型","link":"#openai悄悄上架生命科学新模型","children":[]},{"level":3,"title":"英飞凌ICIC 2026：AI走进物理世界","slug":"英飞凌icic-2026-ai走进物理世界","link":"#英飞凌icic-2026-ai走进物理世界","children":[]},{"level":3,"title":"中科大团队造溯因世界模型获千万融资","slug":"中科大团队造溯因世界模型获千万融资","link":"#中科大团队造溯因世界模型获千万融资","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"从Sigmoid到SwiGLU 读懂激活函数","slug":"从sigmoid到swiglu-读懂激活函数","link":"#从sigmoid到swiglu-读懂激活函数","children":[]},{"level":3,"title":"Agent时代前端：三大UI协议协同模式","slug":"agent时代前端-三大ui协议协同模式","link":"#agent时代前端-三大ui协议协同模式","children":[]},{"level":3,"title":"人生周报v094：AI与人生感悟","slug":"人生周报v094-ai与人生感悟","link":"#人生周报v094-ai与人生感悟","children":[]},{"level":3,"title":"AI逆向一切，软件都将被迫开源","slug":"ai逆向一切-软件都将被迫开源","link":"#ai逆向一切-软件都将被迫开源","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"全球首个机器人原生3D世界模型UNITAS","slug":"全球首个机器人原生3d世界模型unitas","link":"#全球首个机器人原生3d世界模型unitas","children":[]},{"level":3,"title":"清华开源VeriLoop E2 推进黑洞信息悖论研究","slug":"清华开源veriloop-e2-推进黑洞信息悖论研究","link":"#清华开源veriloop-e2-推进黑洞信息悖论研究","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"清华团队样本分布训练刷新生成SOTA","slug":"清华团队样本分布训练刷新生成sota","link":"#清华团队样本分布训练刷新生成sota","children":[]}]}],"git":{"updatedTime":1792660089000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"3bfcc59aee01eb5d30ba6cbbc353e76f499c4b3e","time":1792660089000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-10-22T09:08:09.845Z"}]},"filePathRelative":"posts/2026-10-12.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-10-12 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>Liam Fedus：AI该进实体实验室了</h3>\\n<p>Liam Fedus：当前AI在聊天、编程、数学领域的突破，依赖可验证数据或自然交互产品形态；互联网语料已接近枯竭，AI攻克物理世界难题必须搭建实体实验室。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=8542d73d8eb0290d9649d330f00b380b0345a296ef06c27094c345b3d5b732e2e90f0f37fcf6&amp;idx=1&amp;mid=2651062101&amp;sn=4fa34c4604540b68c52a577eec0cead7#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{p as comp,l as data};
